var DataLoader = class {
  url
  onData
  onComplete
  onError
  workerUrl
  worker
  constructor(url, onData, onComplete, onError, workerUrl) {
    this.url = url
    this.onData = onData
    this.onComplete = onComplete
    this.onError = onError
    this.workerUrl = workerUrl
    this.worker = null
  }
  load() {
    try {
      this.worker = new Worker(this.workerUrl)
      this.worker.onmessage = e64 => {
        const {type, data, error} = e64.data
        if (type === "line") {
          try {
            const parsed = JSON.parse(data)
            this.onData(parsed)
          } catch (parseError) {
            console.warn("[DataLoader] Failed to parse line:", data, parseError)
          }
        } else if (type === "data") {
          this.onData(data)
        } else if (type === "complete") {
          this.onComplete()
          this._cleanup()
        } else if (type === "error") {
          this.onError(error)
          this._cleanup()
        }
      }
      this.worker.onerror = e64 => {
        this.onError(e64.message)
        this._cleanup()
      }
      this.worker.postMessage({url: this.url})
    } catch (error) {
      console.error("[DataLoader] Failed to create worker:", error)
      this.onError(error instanceof Error ? error.message : String(error))
    }
  }
  _cleanup() {
    if (this.worker) {
      this.worker.terminate()
      this.worker = null
    }
  }
}

